export function GovernorCard(n,o){const i=n.reforms.map(n=>`<li>${n}</li>`).join(""),s=n.monetaryPolicy.map(n=>`<li>${n}</li>`).join(""),t=n.achievements.map(n=>`<li>${n}</li>`).join(""),a=n.facts.map(n=>`<p>💡 ${n}</p>`).join("");return`\n        <div class="gov-card" id="gov-${o}">\n            <div class="gov-card-header">\n                <div class="gov-portrait">\n                    <img src="${n.photo}" alt="Portrait of ${n.name}" loading="lazy" onerror="this.src='https://via.placeholder.com/150';" />\n                </div>\n                <div class="gov-title">\n                    <h3>${n.name}</h3>\n                    <p class="gov-term-label">RBI Governor</p>\n                    <p class="gov-meta"><strong>Appointment:</strong> ${n.appointmentDate}</p>\n                    <p class="gov-meta"><strong>Term End:</strong> ${n.endDate}</p>\n                    <p class="gov-meta"><strong>Tenure:</strong> ${n.tenure}</p>\n                </div>\n            </div>\n            <div class="gov-card-body">\n                <div class="gov-section">\n                    <h4>Major Banking Reforms</h4>\n                    <ul>${i}</ul>\n                </div>\n                <div class="gov-section">\n                    <h4>Monetary Policy Contributions</h4>\n                    <ul>${s}</ul>\n                </div>\n                <div class="gov-section">\n                    <h4>Key Achievements</h4>\n                    <ul>${t}</ul>\n                </div>\n                <div class="gov-section gov-facts">\n                    <h4>Interesting Facts</h4>\n                    ${a}\n                </div>\n            </div>\n        </div>\n    `}